unsigned long long simple_strtoull(const char *cp, char **endp, unsigned int base) /* <=== simple_strtoull */ 
{
	unsigned long long result = 0;

	if (!base)
		base = simple_guess_base(cp);

	if (base == 16 && cp[0] == '0' && TOLOWER(cp[1]) == 'x')
		cp += 2;

	while (isxdigit(*cp)) {
		unsigned int value;

		value = isdigit(*cp) ? *cp - '0' : TOLOWER(*cp) - 'a' + 10;
		if (value >= base)
			break;
		result = result * base + value;
		cp++;
	}
	if (endp)
		*endp = (char *)cp;

	return result;
}

static inline void spin_lock_bh(spinlock_t *lock) /* <=== spin_lock_bh */ 
{
	raw_spin_lock_bh(&lock->rlock);
}

static inline void init_completion(struct completion *x) /* <=== init_completion */ 
{
	x->done = 0;
	init_waitqueue_head(&x->wait);
}

static inline char *__strend(const char *s) /* <=== __strend */ 
{
	register unsigned long r0 asm("0") = 0;

	asm volatile ("0: srst  %0,%1\n"
		      "   jo    0b"
		      : "+d" (r0), "+a" (s) :  : "cc" );
	return (char *) r0;
}

